INSERT INTO FactHoldings (SK_CustomerID, SK_AccountID, SK_SecurityID, SK_CompanyID, CurrentPrice, SK_DateID, SK_TimeID, TradeID, CurrentTradeID, CurrentHolding, BatchID) SELECT CAST(DT.SK_CustomerID AS INT) AS SK_CustomerID, CAST(DT.SK_AccountID AS INT) AS SK_AccountID, CAST(DT.SK_SecurityID AS INT) AS SK_SecurityID, CAST(DT.SK_CompanyID AS INT) AS SK_CompanyID, CAST(CASE WHEN TRY_CAST(NULLIF(TRIM(CAST(DT.TradePrice AS TEXT)), '') AS DECIMAL(8, 2)) > 0 THEN TRY_CAST(NULLIF(TRIM(CAST(DT.TradePrice AS TEXT)), '') AS DECIMAL(8, 2)) END AS DECIMAL(8, 2)) AS CurrentPrice, CAST(DT.SK_CloseDateID AS INT) AS SK_DateID, CAST(DT.SK_CloseTimeID AS INT) AS SK_TimeID, CAST(HH.HH_H_T_ID AS INT) AS TradeID, CAST(HH.HH_T_ID AS INT) AS CurrentTradeID, CAST(COALESCE(HH_AFTER_QTY, 0) AS DECIMAL(6, 0)) AS CurrentHolding, CAST(1 AS DECIMAL(5, 0)) AS BatchID FROM Source.HoldingHistory AS HH INNER JOIN DimTrade AS DT ON HH.HH_T_ID = DT.TradeID;
